E["quest:1444"] = {t="quest",n="Return to Fel'Zerul",z="hinterlands",s="In the Hinterlands, the Atal'ai Exile sends word to Fel'zerul in Stonard. The artifacts you brought are harmless, but the exile fears what Jammal'an the Prophet may do.",h="In the Hinterlands, the Atal'ai Exile sends word to Fel'zerul in Stonard.",sec={{t="Words from an Exile",b="The Atal'ai Exile once held Jammal'an the Prophet worthy of the high priesthood. Now the exile fears his unyielding faith in the prophecy may doom the Atal'ai, if it has not already. Speaking out earned the exile the name infidel and banishment from the Temple of Atal'Hakkar.\n\nThe artifacts you brought are harmless. Yet danger may lie in the summoning ritual, for Jammal'an may have found the right fetish enchantment. The world could be in great peril. Fel'zerul in Stonard waits to hear what the exile learned.",sp=0}},faq={{q="Where must I go to speak with Fel'zerul?",a="Fel'zerul is in Stonard.",al={"fel'zerul location","where is fel'zerul","turn in return to fel'zerul"}},{q="Why was the Atal'ai Exile banished?",a="The Atal'ai Exile spoke against Jammal'an the Prophet's unyielding faith in his prophecy, which the exile fears may destroy the Atal'ai. The exile was called an infidel and banished from the Temple of Atal'Hakkar.",al={"why was atal'ai exile banished","why is the exile in hinterlands","atal'ai exile backstory"}},{q="Are the artifacts brought to the exile dangerous?",a="The exile says the artifacts are harmless. The danger lies in the summoning ritual and whether Jammal'an has found the right fetish enchantment for it.",al={"are the artifacts harmful","fetish artifacts danger"}}},kw={"atal'ai exile","fel'zerul","hinterlands","jammal'an","stonard","summoning ritual","temple of atal'hakkar"},rel={"npc:fel-zerul","subzone:stonard","subzone:temple-of-atal-hakkar","zone:hinterlands"},m={start="Atal'ai Exile",["end"]="Fel'zerul",level="44",faction="Horde",id=1444},src={"Wowpedia: Return to Fel'Zerul"}}
E["quest:1450"] = {t="quest",n="Gryphon Master Talonaxe",z="hinterlands",s="Inside the Aerie Peak Aviary, flight assignments fall to Gryphon Master Talonaxe. Falstad Wildhammer sends you there after turning away someone who came for an old Explorers' League friend.",h="Inside the Aerie Peak Aviary, flight assignments fall to Gryphon Master Talonaxe.",sec={{t="Sent Away",b="Falstad Wildhammer has little patience for a visitor sent by an old Explorers' League member. He does not know who that friend once flew with, and flight assignments belong to the gryphon master. You can find Gryphon Master Talonaxe inside the Aerie Peak Aviary. Falstad has real work for anyone who stays nearby.",sp=0},{t="What Talonaxe Remembers",b="Gryphon Master Talonaxe remembers sending a gryphon rider to help Brohann Caskbelly. Talonaxe has long cared for the Explorers' League, for Talonaxe's father helped the first excavation team to find Uldaman. The rider was Rhapsody Shindigger, whom Talonaxe thought the best at the time.",sp=1}},faq={{q="Why does Falstad Wildhammer send you to Talonaxe?",a="Falstad Wildhammer does not know who the Explorers' League friend flew with. So he sends you to the gryphon master, who handles flight assignments.",al={"why see talonaxe","falstad sending away","who is talonaxe"}},{q="Where is Gryphon Master Talonaxe located?",a="Gryphon Master Talonaxe waits inside the Aerie Peak Aviary.",al={"where is talonaxe","talonaxe location","aerie peak aviary"}}},kw={"aerie peak","aviary","brohann caskbelly","explorers league","falstad wildhammer","gryphon master talonaxe","rhapsody shindigger","uldaman"},rel={"quest:1451","topic:explorers-league","subzone:uldaman","zone:hinterlands"},m={start="Falstad Wildhammer",["end"]="Gryphon Master Talonaxe",level="43",faction="Alliance",id=1450},src={"Wowpedia: Gryphon Master Talonaxe (quest)"}}
E["quest:1451"] = {t="quest",n="Rhapsody Shindigger",z="hinterlands",s="At the Aerie Peak Aviary, Talonaxe has news of a fallen flyer. Rhapsody Shindigger was once its finest flyer, but liquor cost Rhapsody the post. Now Rhapsody keeps a brewing camp east of the aviary, in the Hinterlands, Talonaxe has heard.",h="At the Aerie Peak Aviary, Talonaxe has news of a fallen flyer.",sec={{t="A Fallen Flyer",b="Gryphon Master Talonaxe says the aviary dwarves all enjoy a good ale. Rhapsody took to liquor as readily as a gryphon takes to the skies. No one could fly like Rhapsody, and Talonaxe still regrets the loss.\n\nThe trouble began when Rhapsody returned stumbling from a trip with Brohann. Things worsened quickly, and the aviary let Rhapsody go. Talonaxe’s last word is that Rhapsody now keeps a brew camp east of Aerie Peak.",sp=0}},faq={{q="Who sends you to find Rhapsody Shindigger?",a="Gryphon Master Talonaxe at the Aerie Peak Aviary sends you to find Rhapsody.",al={"who starts rhapsody shindigger","who gives rhapsody quest","where to start rhapsody"}},{q="Why was Rhapsody Shindigger let go from the aviary?",a="Rhapsody took to liquor as readily as a gryphon takes to the skies. Trouble began when Rhapsody returned stumbling from a flight with Brohann, then worsened quickly until the aviary let Rhapsody go.",al={"why was rhapsody fired","what happened to rhapsody","rhapsody shindigger backstory"}},{q="Where is Rhapsody now?",a="Talonaxe has heard that Rhapsody now keeps a brew camp east of the aviary, in the Hinterlands.",al={"where is rhapsody shindigger","rhapsody camp location","how to find rhapsody"}}},kw={"aerie peak","aviary","brohann","gryphon master talonaxe","hinterlands","rhapsody shindigger"},rel={"quest:1450","quest:1452","zone:hinterlands"},m={start="Gryphon Master Talonaxe",["end"]="Rhapsody Shindigger",level="43",faction="Alliance",id=1451},src={"Wowpedia: Rhapsody Shindigger (quest)"}}
E["quest:1452"] = {t="quest",n="Rhapsody's Kalimdor Kocktail",z="hinterlands",s="In the Hinterlands, Rhapsody Shindigger is ready to tell you what happened in the swamp, once he has a stiff drink. His Kalimdor Kocktail needs Roc gizzards from Tanaris and Groddoc and Ironfur livers from Feralas.",h="In the Hinterlands, Rhapsody Shindigger is ready to tell you what happened in the swamp, once he has a stiff...",sec={{t="A Stiff Drink",b="Rhapsody greets Brohann's messenger with a hiccup. The two shared quite an adventure, but Rhapsody will tell you what happened in the swamp only after a stiff drink. The tale is not pretty. He has a recipe in mind: the Kalimdor Kocktail. Once it is brewed, he promises to tell you everything.",sp=0},{t="Ingredients from Kalimdor",b="Rhapsody needs three Roc gizzards from Tanaris, three Groddoc livers from Feralas, and three Ironfur livers from Feralas. Even his finest malt cannot help him face the memory of that fateful flight over the swamp.",sp=0}},faq={{q="What does Rhapsody want for the Kalimdor Kocktail?",a="Rhapsody wants three Roc gizzards, three Groddoc livers, and three Ironfur livers for the Kalimdor Kocktail. He wants a stiff drink before telling you what happened in the swamp.",al={"why kocktail","why roc gizzards","why livers"}},{q="Where do the ingredients come from?",a="The Roc gizzards come from Tanaris. The Groddoc and Ironfur livers come from Feralas.",al={"where to find gizzards","cocktail ingredients location","where are groddocs"}},{q="Who sent you to Rhapsody Shindigger?",a="Brohann sent you to Rhapsody Shindigger, who calls Brohann a crazy fool. Before that, Gryphon Master Talonaxe told you where to find Rhapsody.",al={"who sent me to rhapsody","previous quest","brohan"}}},kw={"brohann","feralas","groddoc liver","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard","tanaris"},rel={"quest:1451","quest:1469","zone:hinterlands","zone:feralas","zone:tanaris"},m={start="Rhapsody Shindigger",["end"]="Rhapsody Shindigger",level="43",faction="Alliance",id=1452},src={"Rhapsody's Kalimdor Kocktail"}}
E["quest:1469"] = {t="quest",n="Rhapsody's Tale",z="hinterlands",s="After Rhapsody Shindigger gets his Kalimdor Kocktail, he tells of the flight with Brohann Caskbelly. He gives you an Atal'ai Tablet Fragment to take to Brohann in Stormwind.",h="After Rhapsody Shindigger gets his Kalimdor Kocktail, he tells of the flight with Brohann Caskbelly.",sec={{t="A Fragment for Brohann",b="Rhapsody Shindigger tells you what happened after the kocktail. Before the flight, he drank a whole keg of stout while Brohann followed him through the sky. Rhapsody kept a troll souvenir, an Atal'ai Tablet Fragment. Now he asks you to take it to Brohann Caskbelly in Stormwind.",sp=0},{t="Where the Flight Ended",b="Rhapsody saw no temple from the air. A little too tipsy, he fell from his mount and plunged into the water. The current pulled him down among creepy trolls, and he swam out fast with a souvenir. Brohann's temple lies below the water.",sp=1}},faq={{q="Who receives the Atal'ai Tablet Fragment?",a="Take the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.",al={"who do i give the fragment to","brohann location","where does tablet go"}},{q="What does Rhapsody remember of the flight with Brohann?",a="Before the flight, Rhapsody drank a whole keg of stout, then flew through the sky with Brohann following behind.",al={"why did rhapsody fly","brohann and rhapsody"}},{q="What came before this step?",a="Rhapsody's Kalimdor Kocktail came first. He would not tell the tale until the drink was made.",al={"previous quest","prereq rhapsody's tale"}}},kw={"atal'ai","brohann","caskbelly","fragment","hinterlands","rhapsody","shindigger","stormwind","tablet"},rel={"quest:1452","quest:1451","topic:stormwind-kingdom","topic:troll","zone:hinterlands"},m={start="Rhapsody Shindigger",["end"]="Brohann Caskbelly",level="43",faction="Alliance",id=1469},src={"Wowpedia: Rhapsody's Tale"}}
E["quest:2742"] = {t="quest",n="Rin'ji is Trapped!",z="hinterlands",s="At Quel'Danil Lodge, Rin'ji has lost an axe and is held captive. Rin'ji asks a passer-by for help escaping, offers something in return, and speaks of a secret at the Overlook Cliffs.",h="At Quel'Danil Lodge, Rin'ji has lost an axe and is held captive.",sec={{t="A Plea for Escape",b="At Quel'Danil Lodge, Rin'ji is frightened and held captive. The axe is gone, so Rin'ji begs a passer-by to help escape. Many dislike Rin'ji's kind. Still, Rin'ji offers something to a kind soul who helps and says a secret lies hidden at the Overlook Cliffs.",sp=0},{t="At the End of the Escape",b="A troll tablet bears strange markings. No one can make out what the writing says.",sp=1}},faq={{q="Who is Rin'ji?",a="Rin'ji is a troll who lost an axe and was captured at Quel'Danil Lodge in the Hinterlands. Rin'ji speaks of the self in the third person and begs a passer-by for help escaping.",al={"rinji","who is the troll in quel'danil","who is rin'ji"}},{q="Where is Rin'ji held captive?",a="Rin'ji is held captive at Quel'Danil Lodge in the Hinterlands.",al={"where is rin'ji","rinji location","quel'danil cage"}},{q="What does Rin'ji offer for help?",a="Rin'ji offers something to those who help and says a secret is hidden at the Overlook Cliffs.",al={"what is rin'ji's secret","rinji reward","what is at overlook cliffs"}}},kw={"captive","escort","hinterlands","overlook cliffs","quel'danil","rin'ji","tablet"},rel={"quest:2782","zone:hinterlands","topic:troll"},m={start="Rin'ji",["end"]="Rin'ji's Secret",level="47",faction="Horde",id=2742},src={"Wowpedia: Rin'ji is Trapped!"}}
E["quest:2782"] = {t="quest",n="Rin'ji's Secret",z="hinterlands",s="After helping Rin'ji, you carry Rin'ji's Secret, a tablet marked in Witherbark script that no one has read. Oran Snakewrithe studies the Witherbark and may decipher it. He is known to live in the Magic Quarter of the Undercity.",h="After helping Rin'ji, you carry Rin'ji's Secret, a tablet marked in Witherbark script that no one has read.",sec={{t="A Tablet Nobody Can Read",b="Witherbark troll markings cover the tablet, but what Rin'ji's secret is remains a mystery. It may be worth a great deal or nothing at all. A Witherbark troll in trouble might try anything to escape it.",sp=0},{t="A Scholar in the Undercity",b="Oran Snakewrithe is a well-known scholar of the Witherbark trolls. He is known to live in the Magic Quarter of the Undercity and may be able to read the tablet.",sp=0}},faq={{q="Where did this tablet come from?",a="The tablet is the secret Rin'ji hid at the Overlook Cliffs. You found it after helping Rin'ji escape from Quel'Danil Lodge.",al={"rinji tablet source","how do i get the tablet"}},{q="Who can read the markings on the tablet?",a="Oran Snakewrithe knows the Witherbark trolls well and may be able to decipher the markings.",al={"who can decipher the tablet","who reads witherbark markings"}},{q="Where is Oran Snakewrithe located?",a="Oran Snakewrithe is known to live in the Magic Quarter of the Undercity.",al={"oran snakewrithe location","where is oran"}},{q="Is the tablet valuable?",a="Nobody can say. The tablet may be worth a great deal or nothing at all, since a Witherbark troll in distress might try anything to escape trouble.",al={"what is rinji's secret","tablet meaning"}}},kw={"hinterlands","magic quarter","oran snakewrithe","rin'ji","tablet","undercity","witherbark"},rel={"quest:2742","zone:undercity","subzone:magic-quarter","zone:hinterlands","topic:troll"},m={start="Rin'ji's Secret",["end"]="Oran Snakewrithe",level="47",faction="Horde",id=2782},src={"Rin'ji's Secret (quest)"}}
E["quest:2877"] = {t="quest",n="Skulk Rock Clean-up",z="hinterlands",s="Sludges and oozes overrun the Horde's old positions around Skulk Rock. Fraggar Thundermantle at Aerie Peak wants them cleared, for the Wildhammers have plans for the ground.",h="Sludges and oozes overrun the Horde's old positions around Skulk Rock.",sec={{t="A Matter of Territory",b="The Wildhammers remember the past more than their brothers in Ironforge do. Fraggar Thundermantle says friends are made here by getting your hands dirty. The Horde left its positions around Skulk Rock in the Hinterlands, and sludges and oozes have overrun them. The Wildhammers have plans for that ground, but first the infestation must be thinned.",sp=0},{t="Clearing the Ground",b="Slay ten green sludges and ten jade oozes. Then return to Fraggar at Aerie Peak with your report.",sp=0}},faq={{q="Who is Fraggar Thundermantle?",a="Fraggar Thundermantle is a Wildhammer at Aerie Peak in the Hinterlands. He wants Skulk Rock cleared.",al={"who gives skulk rock clean up","fraggar thundermantle"}},{q="Why do the Wildhammers want Skulk Rock cleared?",a="The Horde left its positions around Skulk Rock, and sludges and oozes have overrun them. The Wildhammers have plans for the area, but first the infestation must be thinned.",al={"why kill the oozes","wildhammer plans skulk rock"}},{q="What creatures dwell at Skulk Rock?",a="Green sludges and jade oozes have overrun the old Horde positions at Skulk Rock.",al={"skulk rock mobs","what is at skulk rock"}},{q="Why does Fraggar bring up Ironforge?",a="Fraggar says the Wildhammers remember the past more than their brothers in Ironforge do. He says friends are made here by getting your hands dirty.",al={"wildhammer ironforge difference","fraggar ironforge"}}},kw={"aerie peak","fraggar thundermantle","green sludge","hinterlands","jade ooze","skulk rock","wildhammer"},rel={"zone:hinterlands","topic:horde"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="48",faction="Alliance",id=2877},src={"Wowpedia: Skulk Rock Clean-up"}}
E["quest:2880"] = {t="quest",n="Troll Necklace Bounty",z="hinterlands",s="At Aerie Peak, Fraggar Thundermantle asks you to bring him five necklaces from trolls in the Hinterlands.",h="At Aerie Peak, Fraggar Thundermantle asks you to bring him five necklaces from trolls in the Hinterlands.",sec={{t="Earning Wildhammer Regard",b="Fraggar Thundermantle trusts deeds over words. The Wildhammers answer to no Alliance, and anyone seeking their friendship must prove their worth first. Trolls roaming the Hinterlands hillsides sometimes wear tribal necklaces. Bring five to Fraggar at Aerie Peak, and you will have made a start.",sp=0}},faq={{q="Why does Fraggar Thundermantle want troll necklaces?",a="Fraggar judges people by their deeds, not their words. Five troll necklaces make a good beginning for anyone seeking Wildhammer friendship.",al={"why troll necklaces","troll necklace bounty purpose","why does fraggar want necklaces"}},{q="Are the Wildhammers part of the Alliance?",a="Fraggar says the Wildhammers are independent and answer to no Alliance. They judge people by their deeds.",al={"are wildhammers alliance","is aerie peak alliance","wildhammer allegiance"}},{q="Where can troll tribal necklaces be found?",a="Trolls roaming the Hinterlands hillsides sometimes carry tribal necklaces.",al={"where to get troll tribal necklace","troll necklace location","how to get troll necklaces"}},{q="Who do I return the necklaces to?",a="Bring the five necklaces to Fraggar Thundermantle at Aerie Peak.",al={"who gets troll necklaces","fraggar thundermantle turn in","where is fraggar thundermantle"}}},kw={"aerie peak","bounty","fraggar thundermantle","hinterlands","troll tribal necklace","trolls","wildhammer"},rel={"zone:hinterlands","topic:troll"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="45",faction="Alliance",id=2880},src={"Wowpedia: Troll Necklace Bounty"}}
E["quest:2881"] = {t="quest",n="Troll Necklace Bounty",z="hinterlands",s="For Fraggar Thundermantle, troll tribal necklaces still come in batches of five. The Wildhammer has already accepted one batch from you, and the offer remains open.",h="For Fraggar Thundermantle, troll tribal necklaces still come in batches of five.",sec={{t="A Standing Offer",b="Fraggar Thundermantle welcomes more troll tribal necklaces whenever you find them and choose to hand them over. He says the Wildhammers will fight for those who fight for them. Each batch must hold five necklaces.",sp=0},{t="Fraggar's Approval",b="Fraggar Thundermantle is pleased when you bring him the necklaces. To him, they prove you are willing to get your hands dirty, a quality the Wildhammers prize.",sp=1}},faq={{q="Who wants the troll tribal necklaces?",a="Fraggar Thundermantle speaks for the Wildhammers.",al={"who gives this bounty","fraggar thundermantle role","who takes the necklaces"}},{q="How many troll tribal necklaces are needed?",a="Five at a time. Fraggar counts a batch only when it holds five necklaces.",al={"necklace count","how many necklaces","bounty requirement"}},{q="Why does Fraggar Thundermantle collect these necklaces?",a="Fraggar treats the necklaces as proof that you are willing to fight for the Wildhammers. He says they will fight for those who do.",al={"why troll necklaces","wildhammer motive","purpose of bounty"}},{q="What came before this bounty?",a="You already completed the first Troll Necklace Bounty for Fraggar Thundermantle.",al={"prerequisite quest","previous step","prior bounty"}}},kw={"fraggar thundermantle","hinterlands","tribal necklace","troll necklace bounty","trolls","wildhammer"},rel={"quest:2880","zone:hinterlands","topic:troll"},m={start="Fraggar Thundermantle",["end"]="Fraggar Thundermantle",level="45",id=2881},src={"Classic quest text: Troll Necklace Bounty"}}
E["quest:2932"] = {t="quest",n="Grim Message",z="hinterlands",s="In Stranglethorn, Nimboya sends you north to punish the Witherbark trolls for betraying Thrall. He gives you a pike to bear their skulls and plant in one of their Hinterlands villages.",h="In Stranglethorn, Nimboya sends you north to punish the Witherbark trolls for betraying Thrall.",sec={{t="A Warning in Blood",b="Nimboya sends you from Stranglethorn to the Hinterlands, far to the north and northeast of Tarren Mill, a village held by the Forsaken. The Witherbark trolls once stood with the Horde, but betrayed Thrall. Hunt them for their skulls, then plant Nimboya's pike in Hiri'watha or Zun'watha, two of their smaller villages. The warning will show them what their deeds cost. Nimboya waits in Stranglethorn.",sp=0}},faq={{q="Why does Nimboya want to punish the Witherbark trolls?",a="The Witherbark trolls once allied with the Horde, then turned against Thrall. Nimboya says their betrayal cannot go unpunished.",al={"why attack witherbark","witherbark betrayal","grim message reason"}},{q="Where does Nimboya send you to plant the pike?",a="Plant the pike in Hiri'watha or Zun'watha, two lesser Witherbark villages in the Hinterlands.",al={"where to plant pike","nimboya pike location","grim message location"}},{q="Where are the Hinterlands from Tarren Mill?",a="The Hinterlands lie northeast of Tarren Mill, the village held by the Forsaken. They lie far north of Nimboya in Stranglethorn.",al={"hinterlands location","where is hinterlands"}},{q="Who gives Grim Message?",a="Nimboya gives you the pike in Stranglethorn and waits there for word.",al={"grim message questgiver","who is nimboya"}}},kw={"grim message","hinterlands","hiri'watha","nimboya","tarren mill","thrall","witherbark","zun'watha"},rel={"npc:thrall","zone:hinterlands","topic:horde","topic:troll","subzone:tarren-mill","topic:forsaken"},m={start="Nimboya",["end"]="Nimboya",level="42",faction="Horde",id=2932},src={"Wowpedia: Grim Message"}}
E["quest:2933"] = {t="quest",n="Venom Bottles",z="hinterlands",s="In the Hinterlands, Venom Bottles fill a Witherbark village. Their great number suggests the Witherbarks value the vile green venom, and an apothecary in nearby Tarren Mill may want a sample.",h="In the Hinterlands, Venom Bottles fill a Witherbark village.",sec={{t="A Toxic Discovery",b="Vile green venom fills bottles throughout the Witherbark village. There are many of them, suggesting the Witherbarks consider the venom important. An apothecary in Tarren Mill may want a sample to examine.",sp=0},{t="Lydon's Verdict",b="Apothecary Lydon has had no success with his experiments that day. He identifies the contents as venom drawn from some arachnoid creature, then asks where the venom came from.",sp=1}},faq={{q="Where are the venom bottles found?",a="The bottles are found in great numbers in a Witherbark village in the Hinterlands.",al={"venom bottle location","where to find venom bottles","witherbark venom"}},{q="Who is interested in the venom bottles?",a="An apothecary in Tarren Mill may want a sample. Apothecary Lydon is the one to see.",al={"who wants the venom","where to turn in venom bottle","tarren mill apothecary"}},{q="What is in the bottles?",a="The bottles hold vile green venom. Their great number suggests the Witherbarks value it highly.",al={"what is the venom","what is in the bottles"}}},kw={"apothecary lydon","arachnoid","hinterlands","tarren mill","troll venom","venom bottle","witherbark"},rel={"zone:hinterlands","subzone:tarren-mill","quest:2934"},m={start="Venom Bottle",["end"]="Apothecary Lydon",level="43",faction="Horde",id=2933},src={"Venom Bottles"}}
E["quest:2934"] = {t="quest",n="Undamaged Venom Sac",z="hinterlands",s="In Tarren Mill, Apothecary Lydon needs a fresh sample of venom. You search the Hinterlands for the spiders that yield it, and the sac must reach him fresh.",h="In Tarren Mill, Apothecary Lydon needs a fresh sample of venom.",sec={{t="A Fresh Sample",b="After Venom Bottles, Apothecary Lydon asks you for a fresher sample. The spiders that yield the venom live in the Hinterlands, many near the troll city of Shadra'Alor. Lydon wants an undamaged venom sac, delivered while it is fresh. He is eager to experiment with it and has ordered several small, terribly cute animals for testing.",sp=0}},faq={{q="Who requests the undamaged venom sac?",a="Apothecary Lydon in Tarren Mill asks you for the sac and waits there for its arrival.",al={"who gives undamaged venom sac","who starts undamaged venom sac","undamaged venom sac quest giver"}},{q="Where can the spiders be found?",a="Many of the spiders live in the Hinterlands near the troll city of Shadra'Alor.",al={"spider location","where are the spiders","where to find undamaged venom sac"}},{q="Why does Apothecary Lydon say not to tarry?",a="The sac must arrive fresh, so Lydon wants you to bring it without delay.",al={"why is it timed","why does the sac spoil","undamaged venom sac timer"}},{q="What came before this step?",a="This follows Venom Bottles, when you brought Lydon a sample of venom from a Witherbark village.",al={"previous quest","what quest comes before undamaged venom sac","undamaged venom sac prerequisite"}}},kw={"apothecary lydon","hinterlands","shadra'alor","spider venom","tarren mill","venom sac"},rel={"quest:2933","quest:2935","subzone:tarren-mill","zone:hinterlands"},m={start="Apothecary Lydon",["end"]="Apothecary Lydon",level="45",faction="Horde",id=2934},src={"Undamaged Venom Sac (quest)"}}
E["quest:2935"] = {t="quest",n="Consult Master Gadrin",z="hinterlands",s="In Sen'jin Village, Apothecary Lydon seeks a stronger venom sample. The broodguard venom you brought was weaker than your first sample, so another kind of spider may be the source.",h="In Sen'jin Village, Apothecary Lydon seeks a stronger venom sample.",sec={{t="A Search for Potency",b="Apothecary Lydon needs a fresh sample of the stronger venom. The broodguard venom you brought was weaker than your first sample, so it must come from another kind of spider.\n\nLydon sends you to Master Gadrin in Sen'jin Village, in Durotar. Gadrin is a troll well acquainted with the Witherbark, and may know where the venom comes from.",sp=0}},faq={{q="Why does Apothecary Lydon send you to Master Gadrin?",a="The broodguard venom was weaker than your first sample, which points to another kind of spider. Master Gadrin knows the Witherbark and may name the venom's source.",al={"why consult gadrin","why go to senjin","lydon gadrin"}},{q="Where is Master Gadrin located?",a="Master Gadrin is in Sen'jin Village, in Durotar.",al={"where is gadrin","master gadrin location","find master gadrin"}},{q="What came before this journey?",a="Before this journey, you brought Apothecary Lydon an undamaged venom sac from the Hinterlands.",al={"prereq","what was before this","previous quest"}}},kw={"apothecary lydon","consult master gadrin","durotar","hinterlands","master gadrin","sen'jin village","venom","witherbark"},rel={"npc:master-gadrin","subzone:sen-jin-village","zone:durotar","zone:hinterlands","topic:troll"},m={start="Apothecary Lydon",["end"]="Master Gadrin",level="45",faction="Horde",id=2935},src={"Consult Master Gadrin"}}
E["quest:2937"] = {t="quest",n="Summoning Shadra",z="hinterlands",s="At Shadra'Alor, you read Master Gadrin's parchment and call Shadra from the Witherbark realm.",h="At Shadra'Alor, you read Master Gadrin's parchment and call Shadra from the Witherbark realm.",sec={{t="Call of the Spider God",b="Master Gadrin sends you deep into the Witherbark realm of the Hinterlands. At Shadra'Alor, you read his parchment at the altar, and Shadra the spider god answers. Defeat her there, then carry her venom to Apothecary Lydon in Tarren Mill.",sp=0}},faq={{q="Who provides the parchment to summon Shadra?",a="Master Gadrin gives you the parchment.",al={"who gives summoning shadra","summoning shadra questgiver"}},{q="Where is Shadra summoned?",a="You summon Shadra at the altar of Shadra'Alor, deep in the Witherbark realm of the Hinterlands.",al={"where to summon shadra","altar of shadra'alor location","shadra location"}},{q="Who receives the venom once Shadra is defeated?",a="After Shadra is defeated, you take her venom to Apothecary Lydon in Tarren Mill.",al={"who do i turn the venom into","summoning shadra turn in","apothecary lydon location"}}},kw={"apothecary lydon","hinterlands","master gadrin","shadra","shadra'alor","spider god","tarren mill","witherbark"},rel={"quest:2938","npc:master-gadrin","zone:hinterlands","subzone:tarren-mill"},m={start="Master Gadrin",["end"]="Apothecary Lydon",level="55",faction="Horde",id=2937},src={"Summoning Shadra (Classic)"}}
E["quest:2938"] = {t="quest",n="Venom to the Undercity",z="hinterlands",s="Apothecary Lydon sends spider god venom to the Undercity. Its strength delights Lydon, who entrusts you with a parcel for Faranell, a superior at the Apothecarium.",h="Apothecary Lydon sends spider god venom to the Undercity.",sec={{t="A Potent Find",b="Apothecary Lydon has killed nearly two dozen rabbits with one dose of the venom. Some were tiny, so their resistance was surely low. Even so, the poison is powerful. Lydon is certain Faranell will want to test it personally, and gives you a parcel for the Apothecarium in the Undercity.",sp=0}},faq={{q="Who is sending the parcel to the Undercity?",a="Apothecary Lydon sends the parcel after testing venom taken from the Witherbark's spider god.",al={"who gives venom to the undercity","quest giver venom to the undercity","who starts venom to the undercity"}},{q="Who is supposed to receive the venom in the Undercity?",a="Master Apothecary Faranell, Lydon's superior, is to receive the venom at the Apothecarium in the Undercity.",al={"who gets the parcel","where does venom go undercity","who is faranell"}},{q="How potent was the venom during testing?",a="One dose killed nearly two dozen rabbits, though some were very young and tiny.",al={"how strong is shadra venom","lydon rabbit tests"}},{q="What comes before this delivery?",a="The delivery follows Summoning Shadra, when the venom was taken from the spider god.",al={"previous quest venom to the undercity","prerequisite venom to the undercity"}}},kw={"apothecarium","apothecary lydon","faranell's parcel","master apothecary faranell","shadra","venom to the undercity"},rel={"npc:master-apothecary-faranell","subzone:apothecarium","zone:undercity","zone:hinterlands"},m={start="Apothecary Lydon",["end"]="Master Apothecary Faranell",level="55",faction="Horde",id=2938},src={"Venom to the Undercity"}}
E["quest:2988"] = {t="quest",n="Witherbark Cages",z="hinterlands",s="At Witherbark Cages, you search for Sharpbeak, heir of Swiftwing, whom Talonaxe calls the mightiest gryphon. Gryphon Master Talonaxe believes the trolls took the young gryphon.",h="At Witherbark Cages, you search for Sharpbeak, heir of Swiftwing, whom Talonaxe calls the mightiest gryphon.",sec={{t="A Missing Heir",b="Gryphon Master Talonaxe asks you to find Sharpbeak, who went missing a few days ago while hunting with his parents. Talonaxe and the others believe the trolls took him. Three cages in the two Witherbark troll villages remain to be checked. Talonaxe awaits your findings.",sp=0},{t="Word From the Villages",b="Sharpbeak is not in the Witherbark villages. Talonaxe takes the news gravely. The young gryphon is meant to lead the next generation. Without him, the fleet would lose much of its strength and spirit.",sp=1}},faq={{q="Who is Sharpbeak?",a="Sharpbeak is Swiftwing's heir, and Talonaxe calls Swiftwing the mightiest gryphon. Sharpbeak went missing a few days ago while hunting with his parents.",al={"sharpbeak","who is the gryphon","swiftwing heir"}},{q="Why are the Witherbark trolls suspected?",a="Talonaxe and the others believe the Witherbark trolls took Sharpbeak. The cages in their two villages are the first places to search.",al={"why trolls","witherbark involvement","who took sharpbeak"}},{q="Where do I search for Sharpbeak?",a="Search the cages in the two Witherbark troll villages. Then return to Gryphon Master Talonaxe and tell him what you found.",al={"where are the cages","witherbark cages location","where to look for sharpbeak"}}},kw={"cages","gryphon","hinterlands","sharpbeak","swiftwing","talonaxe","trolls","witherbark"},rel={"quest:2989","quest:1450","zone:hinterlands","topic:troll","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="45",faction="Alliance",id=2988},src={"Wowpedia: Witherbark Cages"}}
E["quest:2989"] = {t="quest",n="The Altar of Zul",z="hinterlands",s="At the Altar of Zul, Talonaxe's search for Sharpbeak reaches the Vilebranch lands. Witherbark has no sign of the young gryphon, and Talonaxe fears the Vilebranch may hold him.",h="At the Altar of Zul, Talonaxe's search for Sharpbeak reaches the Vilebranch lands.",sec={{t="Another Tribe, Another Search",b="With no sign of Sharpbeak in the Witherbark cages, Gryphon Master Talonaxe suspects the Vilebranch trolls took him. So he sends you to search the top of the Altar of Zul, at the western edge of their lands. If they hold the gryphon child, Talonaxe fears what they may be doing to him.",sp=0},{t="Word From the Altar",b="Sharpbeak is not at the altar. Talonaxe calls that bad news, but good as well. The Vilebranch are known to carry out sacrifices, and he is relieved the gryphon was not found there. He thanks you for your aid and says a greater undertaking lies ahead.",sp=1}},faq={{q="Why does Gryphon Master Talonaxe send you to the Altar of Zul?",a="The Witherbark trolls do not have Sharpbeak, so Talonaxe suspects the Vilebranch may have taken him.",al={"why altar of zul","altar of zul reason","why go to altar of zul"}},{q="Where is the Altar of Zul located?",a="The Altar of Zul lies at the western edge of Vilebranch lands in the Hinterlands. You are to search its top.",al={"altar of zul location","where is altar of zul"}},{q="Who is Sharpbeak?",a="Sharpbeak is Swiftwing's heir, the gryphon child Talonaxe has searched for since he went missing.",al={"who is sharpbeak","sharpbeak lore"}},{q="Why is Talonaxe worried about the Vilebranch trolls?",a="Talonaxe fears what the Vilebranch trolls may be doing to Sharpbeak if they hold him.",al={"why are vilebranch dangerous","what do vilebranch do"}}},kw={"altar of zul","gryphon master talonaxe","hinterlands","sharpbeak","vilebranch","witherbark"},rel={"quest:1450","quest:2988","zone:hinterlands","topic:troll","quest:2992","quest:2993","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="48",faction="Alliance",id=2989},src={"Wowpedia: The Altar of Zul (quest)"}}
E["quest:2990"] = {t="quest",n="Thadius Grimshade",z="hinterlands",s="At Nethergarde Keep, Talonaxe sends you to Thadius Grimshade with a feather from Sharpbeak's nest.",h="At Nethergarde Keep, Talonaxe sends you to Thadius Grimshade with a feather from Sharpbeak's nest.",sec={{t="A Plea to a Diviner",b="Years ago, Thadius Grimshade left Aerie Peak to seek darker knowledge. Yet Talonaxe says he remains a Wildhammer at heart. He hopes Thadius can use divining magic and Sharpbeak's feather to find the gryphon child. Thadius lives in the mage tower at Nethergarde Keep, in the Blasted Lands.",sp=0},{t="The Diviner's Welcome",b="Thadius Grimshade welcomes you as someone bearing a gift. He recognizes the feather as belonging to a fine gryphon, one meant for great things if he grows up unharmed. Then Thadius asks you to listen closely.",sp=1}},faq={{q="Who is Thadius Grimshade?",a="Thadius Grimshade left Aerie Peak years ago to seek darker knowledge. Talonaxe says he remains a Wildhammer at heart.",al={"thadius grimshade lore","who is thadius"}},{q="Why do you need Sharpbeak's feather?",a="Sharpbeak's feather came from the nest where he sleeps. Talonaxe hopes Thadius can use divining magic on it to find the young gryphon.",al={"why sharpbeak feather","feather purpose"}},{q="Where is Thadius Grimshade located?",a="Thadius Grimshade lives in the mage tower at Nethergarde Keep, in the Blasted Lands.",al={"thadius grimshade location","where is thadius"}}},kw={"aerie peak","blasted lands","divination","gryphon","nethergarde keep","sharpbeak","talonaxe","thadius grimshade"},rel={"npc:thadius-grimshade","quest:1450","subzone:nethergarde-keep","zone:blastedlands","zone:hinterlands","quest:2989","quest:2992","quest:2994"},m={start="Gryphon Master Talonaxe",["end"]="Thadius Grimshade",level="47",faction="Alliance",id=2990},src={"Thadius Grimshade (quest)"}}
E["quest:2992"] = {t="quest",n="The Divination",z="hinterlands",s="Thadius Grimshade turns to Sharpbeak’s feather, seeking the gryphon through its trace. He asks you to give him room as he follows the bond to its owner.",h="Thadius Grimshade turns to Sharpbeak’s feather, seeking the gryphon through its trace.",sec={{t="A Ritual of Divination",b="Thadius Grimshade follows the bond between Sharpbeak’s feather and the gryphon who owns it. He hopes to reach Sharpbeak himself, and asks you for silence and room to work. The ritual may not go as planned. If it does not, he warns, you had better close your eyes.",sp=0},{t="When the Ritual Ends",b="Thadius Grimshade reaches Sharpbeak through the ritual. He glimpses the gryphon and can tell you where to look.",sp=1}},faq={{q="What is Thadius Grimshade doing in this ritual?",a="Thadius Grimshade performs a ritual to follow the link between the feather you brought and Sharpbeak. He hopes to reach the gryphon himself.",al={"what is the divination","grimshade ritual","how does grimshade find sharpbeak"}},{q="Who is Sharpbeak?",a="Sharpbeak is the gryphon child whose feather you brought to Thadius Grimshade. Gryphon Master Talonaxe has been trying to find him.",al={"sharpbeak","who is sharpbeak"}},{q="Is the ritual dangerous?",a="Thadius Grimshade warns that if the ritual goes wrong, you had better close your eyes. He asks you to give him room while he works.",al={"is the divination dangerous","why close my eyes","divination risk"}}},kw={"feather","gryphon","ritual","sharpbeak","thadius grimshade","the divination"},rel={"npc:thadius-grimshade","quest:2993","quest:2994","quest:2989","quest:2988","zone:blastedlands"},m={start="Thadius Grimshade",["end"]="Thadius Grimshade",level="47",faction="Alliance",id=2992},src={"The Divination"}}
E["quest:2993"] = {t="quest",n="Return to the Hinterlands",z="hinterlands",s="You carry Thadius Grimshade's news of Sharpbeak to Gryphon Master Talonaxe.",h="You carry Thadius Grimshade's news of Sharpbeak to Gryphon Master Talonaxe.",sec={{t="Where Sharpbeak Is Held",b="Thadius Grimshade has learned where Sharpbeak is held. The gryphon is caged on a high cliff atop Jintha'Alor in the Hinterlands. Vile Priestess Hexx, high priestess of the Vilebranch trolls, holds the key. You bring the news to Gryphon Master Talonaxe.",sp=0},{t="Talonaxe's Answer",b="Gryphon Master Talonaxe cannot bear the news that the Vilebranch trolls hold Sharpbeak. He declares that a force must be organized to bring the gryphon back.",sp=1}},faq={{q="Who reveals the location of Sharpbeak?",a="Thadius Grimshade reveals where Sharpbeak is held after performing a ritual of divination.",al={"who tells you where sharpbeak is","sharpbeak location source","who finds sharpbeak"}},{q="Where is Sharpbeak being held?",a="Sharpbeak is caged on a high cliff atop Jintha'Alor in the Hinterlands.",al={"where is sharpbeak","sharpbeak cage location","sharpbeak cliff"}},{q="Who holds the key to Sharpbeak's cage?",a="Vile Priestess Hexx, high priestess of the Vilebranch trolls, holds the key to Sharpbeak's cage.",al={"sharpbeak key","who has cage key","vile priestess hexx key"}},{q="Where do you deliver this news?",a="You deliver the news to Gryphon Master Talonaxe in the Hinterlands.",al={"who do i return to","where to turn in return to the hinterlands","gryphon master talonaxe location"}},{q="What came before this journey?",a="Thadius Grimshade had just performed the ritual of divination to find Sharpbeak.",al={"previous quest","what led to return to the hinterlands","preceding step"}}},kw={"gryphon master talonaxe","hinterlands","jintha'alor","sharpbeak","thadius grimshade","vile priestess hexx","vilebranch"},rel={"quest:2992","quest:2994","npc:thadius-grimshade","quest:1450","zone:hinterlands","topic:troll","quest:2989","quest:2988"},m={start="Thadius Grimshade",["end"]="Gryphon Master Talonaxe",level="47",faction="Alliance",id=2993},src={"Return to the Hinterlands"}}
E["quest:2994"] = {t="quest",n="Saving Sharpbeak",z="hinterlands",s="At Jintha'Alor, Sharpbeak waits in a cage deep in Vilebranch territory. Gryphon Master Talonaxe sends you to free him, and Vile Priestess Hexx holds the key.",h="At Jintha'Alor, Sharpbeak waits in a cage deep in Vilebranch territory.",sec={{t="Up Jintha'Alor",b="After Thadius Grimshade's divination, you report to Talonaxe. Now the path to Sharpbeak is clear. Jintha'Alor lies at the heart of Vilebranch territory, and you fight your way to its summit. Vile Priestess Hexx holds the key to Sharpbeak's cage. Take it from her, then find the cage and free the gryphon.",sp=0},{t="Talonaxe's Thanks",b="Swiftwind and Keenclaw have brought their child home, and they cannot stop fussing over him. The sight leaves Talonaxe misty-eyed. He says the debt cannot be repaid. Aerie Peak's gryphons and riders will sing your name for a long time.",sp=1}},faq={{q="Who sends you to rescue Sharpbeak?",a="Gryphon Master Talonaxe sends you to rescue Sharpbeak after Thadius Grimshade's divination reveals where the gryphon is held.",al={"who gives saving sharpbeak","sharpbeak questgiver","where do i start saving sharpbeak"}},{q="Where is Sharpbeak being held?",a="Sharpbeak is caged at the summit of Jintha'Alor, in Vilebranch territory in the Hinterlands.",al={"where is sharpbeak","sharpbeak location","where is sharpbeak cage"}},{q="Who holds the key to Sharpbeak's cage?",a="Vile Priestess Hexx has it.",al={"who drops sharpbeak key","where is hexx key","vile priestess hexx key"}}},kw={"aerie peak","gryphon master talonaxe","hinterlands","jintha'alor","saving sharpbeak","sharpbeak","vile priestess hexx","vilebranch"},rel={"quest:2993","quest:2992","zone:hinterlands","npc:thadius-grimshade","quest:2989","quest:2988"},m={start="Gryphon Master Talonaxe",["end"]="Gryphon Master Talonaxe",level="51",faction="Alliance",id=2994},src={"Wowpedia: Saving Sharpbeak"}}
E["quest:4787"] = {t="quest",n="The Ancient Egg",z="hinterlands",s="In Tanaris, Yeh'kinya seeks the ancient egg named in the Prophecy of Mosh'aru. It comes from the age of troll empires, and he wants you to bring it from Jintha'Alor in the Hinterlands.",h="In Tanaris, Yeh'kinya seeks the ancient egg named in the Prophecy of Mosh'aru.",sec={{t="A Relic of Troll Empires",b="The Prophecy of Mosh'aru tells of an ancient egg from the age when trolls ruled vast empires. Its power can contain Hakkar's essence. Yeh'kinya believes it may be the only way to guard the world from his evil.",sp=0},{t="Behind the Amphitheater",b="Yeh'kinya asks you to bring the egg to Tanaris. Tales place it deep inside Jintha'Alor in the Hinterlands, in a cave behind the amphitheater atop the city. Great forces stir, and Yeh'kinya fears time is running short.",sp=0}},faq={{q="What is the ancient egg?",a="A relic from the age when trolls ruled vast empires, told of in the Prophecy of Mosh'aru. Its power can hold Hakkar's essence.",al={"ancient egg lore","what does the egg do","prophecy of mosharu egg"}},{q="Why does Yeh'kinya want the egg?",a="Yeh'kinya believes the egg may be the only way to guard the world from Hakkar's evil.",al={"why find the egg","yehkinya purpose","stop hakkar egg"}},{q="Where is the egg hidden?",a="Tales place the egg deep inside Jintha'Alor in the Hinterlands, in a cave behind the amphitheater atop the city.",al={"where is the ancient egg","ancient egg location","egg cave jinthaalor"}},{q="Who wants the egg brought to them?",a="Yeh'kinya waits in Tanaris and wants you to bring the ancient egg there.",al={"who starts ancient egg","who gives the quest","yehkinya questgiver"}}},kw={"ancient egg","hakkar","hinterlands","jintha'alor","mosh'aru","prophecy","tanaris","yeh'kinya"},rel={"npc:yeh-kinya","zone:hinterlands","zone:tanaris","topic:troll"},m={start="Yeh'kinya",["end"]="Yeh'kinya",level="50",faction="Neutral",id=4787},src={"The Ancient Egg"}}
E["quest:485"] = {t="quest",n="Find OOX-09/HL!",z="hinterlands",s="Near Skulk Rock, a homing robot lies crashed in the Hinterlands. Its gnomish maker, Oglethorpe Obnoticus, calls through a metal egg and asks you to carry a beacon to the wreck.",h="Near Skulk Rock, a homing robot lies crashed in the Hinterlands.",sec={{t="A Crackling Call",b="Turn the knob on the strange metal egg, and a gnomish device opens. A crackling voice gives the name Oglethorpe Obnoticus. His homing robot has crashed, and he has worked out where it came down: where the river begins, near Skulk Rock. Carry the beacon there.",sp=0},{t="The Wreckage at the River",b="At the river's head, you find wreckage shaped like a robotic chicken. Oglethorpe Obnoticus confirms that it is his homing robot. It needs a jump start before it can return to Booty Bay for repairs. Place the beacon inside.",sp=0}},faq={{q="Who is speaking through the distress beacon?",a="A gnome named Oglethorpe Obnoticus is speaking through the distress beacon. His homing robot has crashed in the Hinterlands.",al={"who made the beacon","who is oglethorpe","who is speaking"}},{q="Where did the robot crash?",a="The robot crashed where the river begins, near Skulk Rock in the Hinterlands.",al={"where is the robot","oox 09 hl location","where to find robot"}},{q="What does the homing robot look like?",a="The wreck looks like a robotic chicken.",al={"what is the robot","chicken robot","what does oox look like"}},{q="What is the beacon for?",a="The beacon goes inside the robot to give it the jump start it needs to return to Booty Bay for repairs.",al={"how to activate robot","what to do with the beacon","how to complete find oox-09/hl"}}},kw={"booty bay","distress beacon","hinterlands","homing robot","oglethorpe obnoticus","oox-09/hl","skulk rock"},rel={"quest:836","subzone:booty-bay","zone:hinterlands"},m={start="OOX-09/HL Distress Beacon",["end"]="Homing Robot OOX-09/HL",level="48",faction="Neutral",id=485},src={"Wowpedia: Find OOX-09/HL!"}}
E["quest:77"] = {t="quest",n="A Sticky Situation",z="hinterlands",s="Dran Droffers seeks the original packaging for Hinterlands Honey Ripple. Gilveradin Sunchaser has it and asks for two extra bottles; ten bottles wait in crates around the abandoned Horde base near Skulk Rock.",h="Dran Droffers seeks the original packaging for Hinterlands Honey Ripple.",sec={{t="A Matter of Packaging",b="Dran Droffers seeks Hinterlands Honey Ripple, and Gilveradin Sunchaser has its original packaging. Gilveradin offers to help in return for two extra bottles. Gather ten bottles and bring them back to the camp.",sp=0},{t="Ruins of Skulk Rock",b="Crates of Hinterlands Honey Ripple are scattered around the abandoned Horde base near Skulk Rock. Foul slimes and oozes cling to the ruins. Rumor says a master ooze leads them.",sp=0}},faq={{q="Who wants the Hinterlands Honey Ripple packaged?",a="Dran Droffers seeks Hinterlands Honey Ripple. Gilveradin Sunchaser has its original packaging, meant for Malton's father.",al={"who needs the ripple","dran droffers ripple","who is the packaging for"}},{q="What does Gilveradin charge for the packaging?",a="Gilveradin asks for two extra bottles of the ripple as his fee. Ten bottles are in the crates.",al={"why 10 bottles","gilveradin fee","why so much ripple"}},{q="Where are the crates of Hinterlands Honey Ripple kept?",a="The crates are around the abandoned Horde base near Skulk Rock in the Hinterlands.",al={"ripple location","where is the honey ripple","skulk rock crates"}},{q="What is at the abandoned camp at Skulk Rock?",a="Foul slimes and oozes cling to the ruins, and rumor says a master ooze leads them.",al={"skulk rock monsters","what is at skulk rock","skulk rock oozes"}}},kw={"dran droffers","gilveradin sunchaser","hinterlands","hinterlands honey ripple","oozes","skulk rock","slimes"},rel={"zone:hinterlands","topic:horde"},m={start="Gilveradin Sunchaser",["end"]="Gilveradin Sunchaser",level="48",faction="Horde",id=77},src={"Wowpedia: A Sticky Situation"}}
E["quest:7815"] = {t="quest",n="Snapjaws, Mon!",z="hinterlands",s="In Revantusk Village, Katoom the Angler asks you to deal with saltwater snapjaws ruining his fishing. He wants fifteen turtles killed.",h="In Revantusk Village, Katoom the Angler asks you to deal with saltwater snapjaws ruining his fishing.",sec={{t="Trouble on the Line",b="Katoom the Angler asks you to help him and his neighbours in Revantusk Village. Saltwater snapjaws may look harmless, but they make fishing hard. One tears his line and steals his bait before he can fish for five minutes. Katoom wants you to kill fifteen of the turtles.",sp=0}},faq={{q="Who asks you to hunt the turtles?",a="Katoom the Angler, a fisher in Revantusk Village in the Hinterlands, asks you to hunt the turtles.",al={"who gives snapjaws mon","snapjaws mon quest giver","katoom the angler"}},{q="Why does Katoom want the saltwater snapjaws killed?",a="Katoom says the saltwater snapjaws tear his fishing line and steal his bait. He can scarcely fish for five minutes before one interrupts him.",al={"why kill snapjaws","turtle nuisance","why kill turtles revantusk"}},{q="How many snapjaws need to be slain?",a="You need to kill fifteen saltwater snapjaw turtles.",al={"how many turtles","snapjaw count","snapjaws mon count"}}},kw={"angler","bait","fishing","hinterlands","katoom","revantusk","snapjaws","turtles"},rel={"zone:hinterlands"},m={start="Katoom the Angler",["end"]="Katoom the Angler",level="50",id=7815},src={"Classic quest text: Snapjaws, Mon!"}}
E["quest:7816"] = {t="quest",n="Gammerita, Mon!",z="hinterlands",s="At Revantusk Village, Katoom the Angler wants his best lure back from Gammerita, Mon!, who leads the saltwater snapjaws. Find her and recover it.",h="At Revantusk Village, Katoom the Angler wants his best lure back from Gammerita, Mon!, who leads the...",sec={{t="A Thief Among the Turtles",b="Katoom says Gammerita, Mon! is no ordinary turtle. She leads the saltwater snapjaws, and he calls her a thief. She snapped his best lure off his line. Since then, the fish have not bitten as they once did.",sp=0},{t="Getting the Lure Back",b="Katoom wants you to find Gammerita, Mon! and recover his lure from her stomach. She stays along the coast among the other turtles.",sp=0},{t="Katoom's Hopes",b="With his lure back and fewer snapjaws about, Katoom expects the fish to come in by the heap.",sp=1}},faq={{q="Who is Katoom the Angler?",a="Katoom the Angler fishes at Revantusk Village in the Hinterlands. He asks you to hunt Gammerita, Mon!.",al={"who is katoom","katoom revantusk","katoom location"}},{q="What is Gammerita?",a="Gammerita, Mon! is no ordinary turtle. She leads the saltwater snapjaws, and Katoom calls her a thief.",al={"who is gammerita","what is gammerita","gammerita turtle"}},{q="Why does Katoom want Gammerita dead?",a="Gammerita, Mon! snapped Katoom's best lure off his line, and the fish have not bitten as they once did. He wants it back from her stomach.",al={"why kill gammerita","what did gammerita steal","katoom motive"}},{q="Where can Gammerita be found?",a="Gammerita, Mon! stays on the coast among the other saltwater snapjaw turtles.",al={"where is gammerita","gammerita location","find gammerita"}}},kw={"angler","gammerita","hinterlands","katoom","lure","revantusk","snapjaw","turtle"},rel={"zone:hinterlands"},m={start="Katoom the Angler",["end"]="Katoom the Angler",level="48",id=7816},src={"Classic quest text: Gammerita, Mon!"}}
E["quest:7828"] = {t="quest",n="Stalking the Stalkers",z="hinterlands",s="In Revantusk, Huntsman Markhor names the wolves threatening the village's hunters. He asks you to turn the hunt on them.",h="In Revantusk, Huntsman Markhor names the wolves threatening the village's hunters.",sec={{t="Wolves in Hiding",b="The Hinterlands wilds have already claimed many trolls. Markhor counts Silvermane wolves among the greatest dangers to Revantusk's hunters. They hide among bushes and in the lay of the land, then pounce when the moment is right. He urges you to think as a Silvermane does and hunt the hunters. Every one must be put down.",sp=0},{t="What Markhor Asks",b="Markhor asks you to kill fifteen Silvermane Stalkers and fifteen Silvermane Howlers. They lurk in the Hinterlands wilds.",sp=0},{t="Revantusk's Thanks",b="When the hunt is done, Markhor thanks you for what you have given the Revantusk.",sp=1}},faq={{q="Who asks for the wolves to be hunted?",a="Huntsman Markhor, of Revantusk in the Hinterlands, asks you to hunt the wolves.",al={"who gives stalking the stalkers","quest giver stalking the stalkers","markhor quest"}},{q="Why are the Silvermane wolves such a threat?",a="Silvermane wolves hide among bushes and the lay of the land, then strike when the chance comes. Markhor ranks them among the greatest dangers to Revantusk's hunters, and many trolls have already been lost in the wilds.",al={"why kill silvermane wolves","silvermane wolf threat","why cull wolves hinterlands"}},{q="Which wolves need to be culled?",a="You are asked to hunt fifteen Silvermane Stalkers and fifteen Silvermane Howlers.",al={"what wolves to kill","stalking the stalkers targets","wolf types hinterlands"}},{q="Where are these wolves found?",a="The wolves lurk in the Hinterlands wilds.",al={"where are silvermane wolves","silvermane stalker location","silvermane howler location"}}},kw={"hinterlands wolves","huntsman markhor","revantusk","revantusk village","silvermane howler","silvermane stalker","stalking the stalkers"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",id=7828},src={"Classic quest text: Stalking the Stalkers"}}
E["quest:7829"] = {t="quest",n="Hunt the Savages",z="hinterlands",s="In the Hinterlands, Huntsman Markhor sends you to hunt savage owlbeasts. He asks you to bring down twenty.",h="In the Hinterlands, Huntsman Markhor sends you to hunt savage owlbeasts.",sec={{t="Claws and Beaks",b="Huntsman Markhor warns that savage owlbeasts are among the Hinterlands' most ornery creatures. Their claws and beaks have cost Revantusk many good warriors. He wants every owlbeast you see killed, until you can bear no more bloodshed. Then he will weigh and judge your contribution. Twenty must fall.",sp=0},{t="Clearing the Mind",b="Markhor counsels you to clear your mind of unclean thoughts and join with the wild. Savage owlbeasts roam the Hinterlands wilds.",sp=0},{t="Markhor's Judgment",b="After the hunt, Huntsman Markhor names you a worthy friend to the Revantusk.",sp=1}},faq={{q="Who offers this hunt?",a="Huntsman Markhor, a huntsman from the village of Revantusk in the Hinterlands, offers the hunt.",al={"who gives hunt the savages","hunt the savages quest giver","huntsman markhor quest"}},{q="Why does Markhor want the savage owlbeasts killed?",a="Markhor calls savage owlbeasts ornery. Their claws and beaks have cost Revantusk many good warriors.",al={"why kill savage owlbeasts","reason for hunting owlbeasts","why hunt the savages"}},{q="Where can the savage owlbeasts be found?",a="Markhor says savage owlbeasts roam the Hinterlands wilds.",al={"savage owlbeast location","where are savage owlbeasts","owlbeasts in hinterlands"}},{q="How many savage owlbeasts must be slain?",a="Twenty savage owlbeasts must fall.",al={"how many owlbeasts to kill","hunt the savages requirement"}}},kw={"hinterlands","hunt the savages","huntsman markhor","owlbeasts","revantusk","revantusk village","savage owlbeast"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",id=7829},src={"Classic quest text: Hunt the Savages"}}
E["quest:7830"] = {t="quest",n="Avenging the Fallen",z="hinterlands",s="At Revantusk Village, Markhor turns his anger toward the Skylords. He asks you to slay a Razorbeak Skylord and bring him its plume.",h="At Revantusk Village, Markhor turns his anger toward the Skylords.",sec={{t="Slaying the Skylords",b="Huntsman Markhor of Revantusk Village resents the Wildhammer for training gryphons to slay trolls. He promises justice for the trolls, but first he wants you to strike at the Skylords, the Hinterlands' elder gryphons.\n\nSlay a Razorbeak Skylord and bring its plume back to Markhor. This rare breed lives in the wilds of the Hinterlands. Markhor blames it for breeding murderous young.",sp=0},{t="The Plume Examined",b="Markhor studies the plume and wonders how many hunters the beast devoured before your hand brought it justice.",sp=1}},faq={{q="Who offers this hunt?",a="Huntsman Markhor offers the hunt at Revantusk Village in the Hinterlands.",al={"quest giver","who gives avenging the fallen","markhor location"}},{q="Why does Huntsman Markhor want a Skylord slain?",a="Markhor says the Wildhammer train gryphons to slay trolls. He wants the region's elder gryphons, the Skylords, eradicated, and blames the rare Razorbeak Skylord for breeding murderous young.",al={"why kill razorbeak skylord","why kill skylord","why hunt gryphons"}},{q="Where can a Razorbeak Skylord be found?",a="Markhor says the rare Razorbeak Skylord keeps to the wilds of the Hinterlands.",al={"skylord location","where is razorbeak skylord","skylord plume location"}},{q="What must be brought back to Markhor?",a="The plume of a Razorbeak Skylord, which means slaying one first.",al={"what item do i need","avenging the fallen objective","skylord drop"}}},kw={"avenging the fallen","gryphon","hinterlands","huntsman markhor","razorbeak skylord","revantusk village","skylord plume","wildhammer"},rel={"zone:hinterlands","topic:troll"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="48",faction="Horde",id=7830},src={"Wowpedia: Avenging the Fallen"}}
E["quest:7839"] = {t="quest",n="Vilebranch Hooligans",z="hinterlands",s="In Revantusk Village, Smith Slagtree seeks tools stolen by Vilebranch trolls. A kind-hearted gnome gave him the set after saving his life when he was a young orc.",h="In Revantusk Village, Smith Slagtree seeks tools stolen by Vilebranch trolls.",sec={{t="A Gift From a Gnome",b="Vilebranch trolls took Smith Slagtree's tools when they invaded Revantusk Village. He has spares, but the stolen set came from a kind-hearted gnome who saved his life when he was a young orc. The gift means the world to Slagtree, so he asks you to recover it.",sp=0},{t="Where the Tools Were Seen",b="Markhor saw the tools near the temples of Agol'watha and Shaol'watha in the northeast of the Hinterlands. Slagtree also says to check Skulk Rock. The Vilebranch trolls there are ruthless and murderous.",sp=0}},faq={{q="Why are these stolen tools so important to Smith Slagtree?",a="A kind-hearted gnome gave the tools to Slagtree after saving his life when he was a young orc. Slagtree has spares, but says the gifted set means the world to him.",al={"why does slagtree care about his tools","slagtree lost tools lore","why are slagtrees tools special"}},{q="Who stole the tools from Revantusk Village?",a="Vilebranch trolls stole Smith Slagtree's tools during their invasion of Revantusk Village.",al={"who took the tools","who stole slagtrees tools"}},{q="Where were the missing tools taken?",a="Near the temples of Agol'watha and Shaol'watha, in the northeast of the Hinterlands, where Markhor saw them. Slagtree also points to Skulk Rock.",al={"where are slagtrees tools","where to find the tools","slagtree tool location"}},{q="Who reported seeing the tools after the raid?",a="Markhor told Smith Slagtree where the tools had been seen.",al={"who saw the tools","who reported the stolen tools"}}},kw={"agol'watha","hinterlands","markhor","revantusk village","shaol'watha","skulk rock","slagtree's lost tools","smith slagtree","vilebranch"},rel={"zone:hinterlands","topic:troll"},m={start="Smith Slagtree",["end"]="Smith Slagtree",level="48",faction="Horde",id=7839},src={"Wowpedia: Vilebranch Hooligans"}}
E["quest:7840"] = {t="quest",n="Lard Lost His Lunch",z="hinterlands",s="In the Hinterlands, Lard has run to Revantusk and left the picnic lunch behind. A Vilebranch struck Lard at a private picnic, and now Lard asks you to fetch the food from an island to the north.",h="In the Hinterlands, Lard has run to Revantusk and left the picnic lunch behind.",sec={{t="A Picnic Interrupted",b="A Vilebranch struck Lard with a big stick at a secret picnic spot. By Lard's account, the troll was ugly and mean. Lard fled to Revantusk, leaving the lunch behind and fearing a return.",sp=0},{t="The Island Northward",b="Lard's picnic spot lies on an island to the north. Lard hopes you will find the lunch and bring it back. Take care around the Vilebranch trolls.",sp=0},{t="Lard's Thanks",b="Lard's lunch is a huge haunch of meat. Lard wolfs it down, thanks you, and promises a special picnic basket for your help.",sp=1}},faq={{q="Who is Lard?",a="Lard lives in Revantusk in the Hinterlands. Hungry and frightened, Lard fled after a Vilebranch struck Lard with a big stick.",al={"lard hinterlands","who is lard","lard revantusk"}},{q="Where did Lard lose his lunch?",a="Lard left the lunch at a secret picnic spot on an island to the north.",al={"where is lards lunch","lard picnic spot","lards secret spot"}},{q="Why did Lard leave his food behind?",a="A Vilebranch struck Lard with a big stick during the picnic. Lard ran back to Revantusk without the lunch.",al={"why did lard run","who attacked lard"}},{q="What should you watch out for on the island?",a="Lard names the Vilebranch trolls as a danger on the island.",al={"vilebranch on island","dangers lards island"}}},kw={"hinterlands","island","lard","lunch","picnic","revantusk village","vilebranch"},rel={"zone:hinterlands"},m={start="Lard",["end"]="Lard",level="49",id=7840},src={"Classic quest text: Lard Lost His Lunch"}}
E["quest:7841"] = {t="quest",n="Message to the Wildhammer",z="hinterlands",s="At Revantusk Village, Otho Moji'ko wants a message carried to the Wildhammer dwarves. Their new allies include the high elves, and Otho wants his warning written in the blood of the Highvale high elves at Quel'Danil Lodge.",h="At Revantusk Village, Otho Moji'ko wants a message carried to the Wildhammer dwarves.",sec={{t="A Message in Blood",b="The Wildhammer are making alliances with the trolls' enemies, and now the high elves stand with them. Otho Moji'ko spits at the thought. He wants the dwarves warned in the blood of their new friends. Slaughter every Highvale high elf you find and leave the bodies as a warning.\n\nHighvale Outrunners, Scouts, Marksmen and Rangers gather at Quel'Danil Lodge, in the northwest of the Hinterlands.",sp=0},{t="Word at Revantusk Village",b="When you return to Revantusk Village, Otho declares that the Revantusk are making new alliances too. He praises your work.",sp=1}},faq={{q="Who offers this quest?",a="Otho Moji'ko offers it from Revantusk Village.",al={"who gives message to the wildhammer","otho mojiko quest"}},{q="Where are the Highvale high elves located?",a="The Highvale high elves gather at Quel'Danil Lodge, in the northwest of the Hinterlands.",al={"quel danil lodge location","where are highvale elves","where to find highvale scouts"}},{q="Why does Otho Moji'ko want the high elves attacked?",a="Otho says the Wildhammer are striking deals with the trolls' enemies, and now they are working with the high elves. He wants a message carried to the Wildhammer dwarves, written in the blood of the high elves.",al={"why attack quel danil","why kill high elves hinterlands"}},{q="Which Highvale elves does Otho want slaughtered?",a="Otho wants the Highvale Outrunners, Scouts, Marksmen and Rangers at Quel'Danil Lodge slaughtered.",al={"which highvale elves","highvale marksman","highvale ranger"}}},kw={"highvale","hinterlands","message to the wildhammer","otho mojiko","quel'danil lodge","revantusk village","wildhammer"},rel={"zone:hinterlands","topic:troll","quest:7842","quest:7843"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="48",faction="Horde",id=7841},src={"Wowpedia: Message to the Wildhammer"}}
E["quest:7842"] = {t="quest",n="Another Message to the Wildhammer",z="hinterlands",s="At Revantusk Village, Otho Moji'ko sends another message to the Wildhammer. He sees their bond with gryphons as close as a troll and a mate, and means to turn it against them.",h="At Revantusk Village, Otho Moji'ko sends another message to the Wildhammer.",sec={{t="A Message of Feathers",b="After the Highvale high elves, Otho Moji'ko has another message for the Wildhammer. Their closeness with gryphons disgusts him, but he sees a use for it. Kill the gryphons you meet across the Hinterlands and gather their Long Elegant Feathers. Gryphons live in every region there. Otho will make his final message from the feathers.",sp=0},{t="Otho's Pleasure",b="Otho expects his final message to frighten the Wildhammer away or make them furious. He delights that only one step remains before they learn trolls cannot be crossed.",sp=1}},faq={{q="Who gives this quest?",a="Otho Moji'ko gives the message from Revantusk Village.",al={"who gives another message to the wildhammer","another message questgiver","otho mojiko"}},{q="Why does Otho Moji'ko want gryphon feathers?",a="Otho says the Wildhammer and their gryphons are as close as a troll and a mate. He means to use that bond against them, and make his final message from the feathers.",al={"why gryphon feathers","why kill gryphons hinterlands"}},{q="Where can gryphons be found?",a="Gryphons live in every region of the Hinterlands.",al={"gryphon locations hinterlands","where are hinterlands gryphons"}},{q="What came before this message?",a="This follows Message to the Wildhammer, in which Otho had Highvale high elves slaughtered as a warning to the dwarves.",al={"what comes before another message to the wildhammer","message to the wildhammer chain"}}},kw={"gryphon","hinterlands","long elegant feather","otho moji'ko","revantusk village","wildhammer"},rel={"quest:7841","quest:7843","zone:hinterlands","topic:troll"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="48",faction="Horde",id=7842},src={"Wowpedia: Another Message to the Wildhammer"}}
E["quest:7843"] = {t="quest",n="The Final Message to the Wildhammer",z="hinterlands",s="At Revantusk Village, Otho Moji'ko sends you west with a blood-soaked spear bound in gryphon feathers. The Wildhammer dwarves will find it planted beside the well at Aerie Peak's heart.",h="At Revantusk Village, Otho Moji'ko sends you west with a blood-soaked spear bound in gryphon feathers.",sec={{t="A Spear for Aerie Peak",b="After Another Message to the Wildhammer, Otho Moji'ko gives you a spear soaked in blood and bound with gryphon feathers. Carry it west to Aerie Peak and plant it beside the well at the town's heart. The Wildhammer dwarves will see that the trolls mean business. Furious dwarves and rowdy Alliance folk await you there, and Otho hopes you return alive.",sp=0},{t="Otho's Hope",b="Otho wonders how the dwarves will react when they see the spear. He wishes he could have seen their faces. Are they packing their bags to leave town? For carrying out the deed, Otho promises you the big mojo.",sp=1}},faq={{q="Who sends you to plant the spear?",a="Otho Moji'ko sends you from Revantusk Village.",al={"quest giver","who gives the quest","otho mojiko"}},{q="Where must the spear be planted?",a="Plant the spear beside the well at the heart of Aerie Peak, in the west of the Hinterlands.",al={"spear location","where do i place the spear","aerie peak well"}},{q="What is the final message made of?",a="The final message is a spear soaked in blood and bound with gryphon feathers.",al={"what is the spear","gryphon feathers spear","the final message item"}},{q="What came before this in the chain?",a="Another Message to the Wildhammer came first. Otho called for gryphon feathers to make this final message.",al={"previous quest","prerequisites","wildhammer message chain"}}},kw={"aerie peak","gryphon feathers","hinterlands","otho moji'ko","revantusk village","spear","wildhammer"},rel={"quest:7842","quest:7841","zone:hinterlands","topic:troll","topic:alliance"},m={start="Otho Moji'ko",["end"]="Otho Moji'ko",level="50",faction="Horde",id=7843},src={"Wowpedia: The Final Message to the Wildhammer"}}
E["quest:7844"] = {t="quest",n="Cannibalistic Cousins",z="hinterlands",s="In the Hinterlands, Mystic Yayo'jin asks you to strike at the Vilebranch near their temples. She calls them a depraved lot who prey on other trolls and humanoids. With Zul'jin away, the Revantusk are left to their own devices.",h="In the Hinterlands, Mystic Yayo'jin asks you to strike at the Vilebranch near their temples.",sec={{t="Three Tribes, One Land",b="Three troll tribes share the Hinterlands, though Mystic Yayo'jin says little binds them. The Vilebranch prey on other trolls and humanoids. Zul'jin could wipe them out with ease, but he is away. So the Revantusk are left to their own devices.",sp=0},{t="Where the Vilebranch Gather",b="Yayo'jin asks you to destroy the Vilebranch Scalpers and Soothsayers near the Shaol'watha and Agol'watha temples. The temples lie in the Hinterlands' north by northeast.",sp=0},{t="Yayo'jin's Praise",b="When you return, Yayo'jin says even Zul'jin could not have done better.",sp=1}},faq={{q="Who offers this quest?",a="Mystic Yayo'jin offers it from Revantusk Village.",al={"cannibalistic cousins quest giver","who gives cannibalistic cousins","mystic yayojin"}},{q="Why does Yayo'jin want the Vilebranch destroyed?",a="Yayo'jin calls the Vilebranch a depraved lot who prey on other trolls and humanoids. She says the region's filth falls to you to destroy.",al={"why revantusk fight vilebranch","vilebranch cannibalism","revantusk vilebranch conflict"}},{q="Where can the Vilebranch trolls be found?",a="The Vilebranch gather around the Shaol'watha and Agol'watha temples, in the Hinterlands' north by northeast.",al={"shaolwatha location","agolwatha location","where are vilebranch soothsayers"}},{q="Which Vilebranch does Yayo'jin want destroyed?",a="Yayo'jin wants the Vilebranch Scalpers and Vilebranch Soothsayers destroyed.",al={"cannibalistic cousins targets","who do i kill for cannibalistic cousins"}},{q="Where is Zul'jin?",a="Zul'jin is not in the Hinterlands. Yayo'jin says he could wipe out the Vilebranch with ease, but he is away, leaving the Revantusk to their own devices.",al={"is zuljin here","where is zuljin hinterlands","zul'jin status"}}},kw={"agol'watha","cannibalistic cousins","mystic yayo'jin","revantusk village","scalper","shaol'watha","soothsayer","vilebranch","zul'jin"},rel={"zone:hinterlands","topic:troll"},m={start="Mystic Yayo'jin",["end"]="Mystic Yayo'jin",level="48",faction="Horde",id=7844},src={"Wowpedia: Cannibalistic Cousins"}}
E["quest:7845"] = {t="quest",n="Kidnapped Elder Torntusk!",z="hinterlands",s="At Revantusk Village, Primal Torntusk asks you to save her mate after a bold midnight raid. Her spies say Elder Torntusk is alive atop Jintha'alor.",h="At Revantusk Village, Primal Torntusk asks you to save her mate after a bold midnight raid.",sec={{t="A Midnight Raid",b="Vilebranch savages struck Revantusk Village at midnight and seized Elder Torntusk, Primal Torntusk's mate. Her spies say he is alive, held prisoner atop Jintha'alor, the Vilebranch capital in the southern Hinterlands. Primal Torntusk fears the village could not bear to lose him.",sp=0},{t="The Faceless Blood God",b="Vile Priestess Hexx is said to be preparing Elder Torntusk for sacrifice to Hakkar, the faceless blood God.",sp=0},{t="Once You Reach Him",b="Elder Torntusk is within reach, but the guards surely know you have arrived. Move quickly.",sp=1}},faq={{q="Who took Elder Torntusk?",a="Vilebranch savages took Elder Torntusk in a bold midnight raid on Revantusk Village.",al={"who kidnapped elder torntusk","who took torntusk","kidnappers of torntusk"}},{q="Where is Elder Torntusk being held?",a="Primal Torntusk's spies say Elder Torntusk is a prisoner atop Jintha'alor, the Vilebranch capital in the southern Hinterlands.",al={"elder torntusk location","where is elder torntusk","where is torntusk captive"}},{q="What fate awaits Elder Torntusk atop Jintha'alor?",a="Sacrifice. Word is that Vile Priestess Hexx is readying Elder Torntusk as an offering to Hakkar, the faceless blood God.",al={"why was torntusk captured","what do vilebranch want with torntusk","hexx sacrifice torntusk"}},{q="Who is Primal Torntusk?",a="Primal Torntusk is Elder Torntusk's mate, and she asks you to save him.",al={"who is primal torntusk","primal torntusk mate"}}},kw={"elder torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},rel={"quest:7846","quest:7847","zone:hinterlands"},m={start="Primal Torntusk",["end"]="Elder Torntusk",level="51",faction="Horde",id=7845},src={"Wowpedia: Kidnapped Elder Torntusk!"}}
E["quest:7846"] = {t="quest",n="Recover the Key!",z="hinterlands",s="At Jintha'alor, Elder Torntusk is shackled and asks you to free him. Hitah'ya the Keeper holds his key in a guarded cave nearby.",h="At Jintha'alor, Elder Torntusk is shackled and asks you to free him.",sec={{t="The Keeper's Cave",b="After Kidnapped Elder Torntusk!, you find Elder Torntusk shackled at Jintha'alor. Hitah'ya the Keeper keeps the key to his bindings in a nearby cave, where she is well guarded. Elder Torntusk asks you to kill her and bring back the key. Then he can loosen his shackles and return home.",sp=0},{t="Elder Torntusk's Thanks",b="With the key, Elder Torntusk gets to his feet. He thanks you and says the Revantusk will hear of your deeds.",sp=1}},faq={{q="Who holds the key to Elder Torntusk's shackles?",a="Hitah'ya the Keeper holds the key to Elder Torntusk's shackles. He says she is in a nearby cave, where she is well guarded.",al={"who has the key","hitahya the keeper","where is the shackle key"}},{q="Where is Elder Torntusk held?",a="Elder Torntusk is held at Jintha'alor.",al={"where is elder torntusk","torntusk location","jintha'alor torntusk"}},{q="Why does Elder Torntusk need the key?",a="The key opens Elder Torntusk's shackles. He says he can return home once he is free.",al={"why the shackle key","what is the key for"}}},kw={"elder torntusk","hinterlands","hitah'ya the keeper","jintha'alor","recover the key","revantusk","shackle key"},rel={"quest:7845","quest:7847","zone:hinterlands"},m={start="Elder Torntusk",["end"]="Elder Torntusk",level="51",faction="Horde",id=7846},src={"Wowpedia: Recover the Key!"}}
E["quest:7847"] = {t="quest",n="Return to Primal Torntusk",z="hinterlands",s="Elder Torntusk is free and sends you to Revantusk Village with word for his mate, Primal Torntusk.",h="Elder Torntusk is free and sends you to Revantusk Village with word for his mate, Primal Torntusk.",sec={{t="News for His Mate",b="Elder Torntusk is free of his bindings and asks you to return to Revantusk Village. Tell his mate, Primal Torntusk, that he is coming home.",sp=0},{t="The Village Is Grateful",b="Primal Torntusk thanks you for serving the Revantusk. The village owes you a deep debt of gratitude.",sp=1}},faq={{q="Who sends you on this journey?",a="Elder Torntusk sends you to carry news of his rescue to his mate.",al={"who starts return to primal torntusk","elder torntusk quest giver"}},{q="Where is Primal Torntusk located?",a="Primal Torntusk is at Revantusk Village in the Hinterlands.",al={"where is primal torntusk","primal torntusk location","where to turn in return to primal torntusk"}},{q="What am I supposed to tell Primal Torntusk?",a="Tell Primal Torntusk that Elder Torntusk is coming home.",al={"what to tell primal torntusk","torntusk message"}},{q="What came before this journey?",a="This follows Recover the Key!, after the earlier effort that began in Kidnapped Elder Torntusk!.",al={"previous quest","primal torntusk quest chain"}}},kw={"elder torntusk","hinterlands","jintha'alor","primal torntusk","revantusk","revantusk village"},rel={"quest:7846","quest:7845","zone:hinterlands"},m={start="Elder Torntusk",["end"]="Primal Torntusk",level="51",faction="Horde",id=7847},src={"Wowpedia: Return to Primal Torntusk"}}
E["quest:7849"] = {t="quest",n="Separation Anxiety",z="hinterlands",s="Huntsman Markhor grieves for his twin, Malkhor, in Revantusk Village. The Vilebranch took Malkhor in the raid that took Torntusk's mate. Markhor believes Malkhor's soul can still be rescued, though his life is beyond saving. So he asks you to recover the remains.",h="Huntsman Markhor grieves for his twin, Malkhor, in Revantusk Village.",sec={{t="A Twin's Loss",b="Many in Revantusk Village have lost loved ones to the wilds, Markhor says. His own grief is for his twin brother, Malkhor. The Vilebranch took Malkhor in the raid that took Torntusk's mate. His captors killed him swiftly and brutally; he was not fated to live.",sp=0},{t="Where the Remains Lie",b="The Vilebranch fed Malkhor's remains to their oozes and wolves. Near the top of the temple of Jintha'alor are a refuse pit filled with oozes and a wolf den. His bones rest in a sludge pit near the top tier, while his skull lies on the tier itself. Markhor plans to carry the remains to Yayo'jin, who will prepare them for a proper burial.",sp=0}},faq={{q="Who was Huntsman Malkhor?",a="Malkhor was Huntsman Markhor's twin brother. The Vilebranch took him in the raid that also took Torntusk's mate, then killed him swiftly and brutally.",al={"who is malkhor","markhors brother","malkhor lore"}},{q="Where were Malkhor's remains taken?",a="The Vilebranch fed Malkhor's remains to their oozes and wolves. His skull lies on Jintha'alor's top tier, while his bones rest in a sludge pit near that tier.",al={"where are the bones","where is malkhors skull","jintha'alor remains"}},{q="Who will prepare Malkhor for burial?",a="Markhor will take Malkhor's remains to Yayo'jin, who will prepare them for a proper burial.",al={"burial for malkhor","who is yayojin","yayo'jin"}},{q="Why does Markhor need the bones returned?",a="Markhor says Malkhor's life is beyond saving, but his soul can still be rescued. He wants the remains recovered so that Malkhor's soul may be saved.",al={"why recover remains","save malkhors soul","saving his soul"}}},kw={"bones","hinterlands","jintha'alor","malkhor","markhor","revantusk","skull","vilebranch","yayo'jin"},rel={"zone:hinterlands"},m={start="Huntsman Markhor",["end"]="Huntsman Markhor",level="50",faction="Horde",id=7849},src={"Wowpedia: Separation Anxiety (quest)"}}
E["quest:7850"] = {t="quest",n="Dark Vessels",z="hinterlands",s="In Revantusk Village, Primal Torntusk says the Vilebranch fight with a fury beyond the natural. He blames Vile Priestess Hexx's foul magic and asks you to take the tainted blood vessels from Jintha'alor, so he can cleanse them.",h="In Revantusk Village, Primal Torntusk says the Vilebranch fight with a fury beyond the natural.",sec={{t="The Vilebranch Fury",b="Across Jintha'alor, tainted blood vessels bear the power of the faceless blood God. That power strengthens the Vilebranch and drives them mad. Torntusk believes taking the vessels away and cleansing them will loosen the blood God's grip on the trolls.",sp=0},{t="After the Vessels Return",b="Returning the vessels lifts the dark energy compelling the Vilebranch, though only for now. Torntusk warns you to watch for evil, for a fallen priestess is soon replaced by another.",sp=1}},faq={{q="Who gives the quest Dark Vessels?",a="Primal Torntusk asks you in Revantusk Village, in the Hinterlands.",al={"who gives dark vessels","dark vessels questgiver"}},{q="Where are the tainted vessels located?",a="The tainted blood vessels lie throughout Jintha'alor in the Hinterlands.",al={"where are dark vessels","vessels of tainted blood location","find tainted blood"}},{q="Why are the Vilebranch trolls so ferocious?",a="Primal Torntusk blames the foul magic of Vile Priestess Hexx. The tainted blood vessels also carry the faceless blood God's power, which strengthens the Vilebranch and drives them mad.",al={"why are vilebranch crazy","vilebranch madness","vilebranch ferocity"}},{q="What does Primal Torntusk plan to do with the vessels?",a="Torntusk plans to cleanse the vessels and loosen the faceless blood God's grip on the Vilebranch.",al={"why collect the vessels","what happens to the blood vessels"}}},kw={"blood god","dark vessels","jintha'alor","primal torntusk","revantusk village","tainted blood","vile priestess hexx","vilebranch"},rel={"zone:hinterlands"},m={start="Primal Torntusk",["end"]="Primal Torntusk",level="50",faction="Horde",id=7850},src={"Wowpedia: Dark Vessels (Classic)"}}
E["quest:7861"] = {t="quest",n="Wanted: Vile Priestess Hexx and Her Minions",z="hinterlands",s="Primal Torntusk has sent you to Jintha'alor to bring Vile Priestess Hexx and her minions to justice. He offers a grand prize for slaying Hexx and her elite Aman'zasi guard.",h="Primal Torntusk has sent you to Jintha'alor to bring Vile Priestess Hexx and her minions to justice.",sec={{t="A Strike at Jintha'alor",b="Primal Torntusk sends you after Vile Priestess Hexx and her minions. They are atop Jintha'alor in the Hinterlands, where Hexx's elite Aman'zasi guards stand with her. Slay them, then report to Torntusk at Revantusk Village.",sp=0}},faq={{q="Who posted the bounty for Vile Priestess Hexx?",a="Primal Torntusk ordered the bounty and offers a grand prize for slaying the priestess and her guard.",al={"who wants hexx dead","who gave this bounty","priestess hexx quest giver"}},{q="Where can Vile Priestess Hexx and her guards be found?",a="Vile Priestess Hexx and her guards are atop Jintha'alor in the Hinterlands.",al={"where is hexx","vile priestess hexx location","amanzasi guards location"}},{q="Who must be slain to fulfill the bounty?",a="Slay Priestess Hexx and her elite Aman'zasi guard of the Vilebranch.",al={"hexx bounty objectives","who to kill for hexx"}},{q="Where is the bounty turned in?",a="After slaying the priestess and her guard, report to Primal Torntusk at Revantusk Village.",al={"where to turn in hexx bounty","primal torntusk location"}}},kw={"aman'zasi","hexx","hinterlands","jintha'alor","primal torntusk","revantusk village","vile priestess hexx","vilebranch"},rel={"zone:hinterlands"},m={start="Call to Arms!",["end"]="Primal Torntusk",level="51",faction="Horde",id=7861},src={"Wowpedia: Wanted: Vile Priestess Hexx and Her Minions"}}
E["quest:7862"] = {t="quest",n="Job Opening: Guard Captain of Revantusk Village",z="hinterlands",s="Revantusk Village needs a new leader for its guard. Applicants must prove themselves against four kinds of Vilebranch and bring an application to Primal Torntusk.",h="Revantusk Village needs a new leader for its guard.",sec={{t="A Vacant Post",b="Guard Captain Malkhor has been lost, leaving Revantusk's guard without a captain once more. The notice calls on anyone who wants to lead the guard to complete its work and send an application to Primal Torntusk.",sp=0},{t="Proving Worth",b="To seek the captaincy, defeat Vilebranch Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters. Then return to Primal Torntusk in Revantusk Village.",sp=0}},faq={{q="Why is the position of Guard Captain open?",a="Guard Captain Malkhor was lost, leaving the captaincy vacant again.",al={"why is guard captain open","what happened to malkhor","who was previous captain"}},{q="Who receives the application once the enemies are slain?",a="Bring the application to Primal Torntusk in Revantusk Village.",al={"who do i turn this in to","where to submit application","who evaluates the applicants"}},{q="Which enemies must be defeated to qualify?",a="Applicants must defeat Vilebranch Berserkers, Shadow Hunters, Blood Drinkers and Soul Eaters.",al={"which vilebranch to kill","job opening targets","who do i kill for guard captain"}}},kw={"berserker","blood drinker","guard captain","malkhor","revantusk","shadow hunter","soul eater","torntusk","vilebranch"},rel={"zone:hinterlands"},m={start="Call to Arms!",["end"]="Primal Torntusk",level="51",faction="Horde",id=7862},src={"Wowpedia: Job Opening: Guard Captain of Revantusk Village"}}
E["quest:8273"] = {t="quest",n="Oran's Gratitude",z="hinterlands",s="You bring Oran Snakewrithe a tablet, and Rin'ji's chain reaches its end.",h="You bring Oran Snakewrithe a tablet, and Rin'ji's chain reaches its end.",sec={{t="A Tablet for Oran",b="After Rin'ji's Secret, you carry the tablet to Oran Snakewrithe. You place it in his hands.",sp=0},{t="Oran's Answer",b="You tell Oran Snakewrithe the tablet came from a small, deserted island at the Overlook Cliffs. He finds the discovery very interesting and carefully puts the tablet away. Then he says the Dark Lady will be very pleased.",sp=1}},faq={{q="Who is Oran Snakewrithe?",a="Oran Snakewrithe receives the tablet at the end of the chain that began with Rin'ji is Trapped! and continued through Rin'ji's Secret.",al={"oran","who is oran","oran snakewrithe lore"}},{q="What comes before this in the chain?",a="Rin'ji's Secret comes before this, preceded by Rin'ji is Trapped!.",al={"previous quest","prereq for oran's gratitude","how to start oran's gratitude"}}},kw={"dark lady","hinterlands","oran snakewrithe","overlook cliffs","rin'ji","tablet"},rel={"quest:2782","quest:2742","zone:hinterlands"},m={start="Oran Snakewrithe",["end"]="Oran Snakewrithe",level="47",faction="Horde",id=8273},src={"Oran's Gratitude"}}
E["quest:836"] = {t="quest",n="Rescue OOX-09/HL!",z="hinterlands",s="Beyond Overlook Cliff, OOX-09/HL needs your help reaching the shore. Oglethorpe Obnoticus speaks through the fallen robot and asks you to escort it there. He waits in Booty Bay afterward.",h="Beyond Overlook Cliff, OOX-09/HL needs your help reaching the shore.",sec={{t="A Walk to the Shore",b="Oglethorpe's voice crackles from the robot again. OOX-09/HL needs an open, safe place for its lengthy take-off procedure, and the shoreline beyond Overlook Cliff will do. Its built-in cloaking cannot yet be used. Oglethorpe needs time to make it work again.",sp=0},{t="Word in Booty Bay",b="When OOX-09/HL reaches the shore safely, Oglethorpe Obnoticus asks you to speak with him in Booty Bay.",sp=0}},faq={{q="Where does the robot need to be escorted?",a="Take OOX-09/HL to the shoreline beyond Overlook Cliff. There, it has room to begin its take-off.",al={"where does oox-09 go","hinterlands chicken escort destination","overlook cliff shore"}},{q="Who is responsible for creating this homing robot?",a="The gnome Oglethorpe Obnoticus created the robot. He is in Booty Bay.",al={"who made oox-09","oox creator","who built the chicken"}},{q="Why can't the robot simply take off where it was found?",a="The lengthy take-off needs an open, safe place. Oglethorpe also needs time to make the robot's cloaking work again.",al={"why does the chicken walk","why escort oox-09"}},{q="Where do you go once the escort reaches the shore?",a="Once OOX-09/HL is safely at the shore, Oglethorpe Obnoticus asks you to meet him in Booty Bay.",al={"where to turn in rescue oox-09","who do i report to","oglethorpe location"}},{q="What came before this escort?",a="This follows Find OOX-09/HL!, when you carried the distress beacon to the crashed robot.",al={"oox-09 previous quest","prerequisite for rescue oox-09"}}},kw={"booty bay","cloaking","homing robot","oglethorpe obnoticus","overlook cliff","oox-09/hl"},rel={"quest:485","zone:hinterlands","subzone:booty-bay"},m={start="Homing Robot OOX-09/HL",["end"]="Oglethorpe Obnoticus",level="48",id=836},src={"Wowpedia: Rescue OOX-09/HL!"}}
E["zone:hinterlands"] = {t="zone",n="The Hinterlands",z="hinterlands",s="The Hinterlands still bear the Amani's old claims, while Wildhammer dwarves hold Aerie Peak. Forest trolls keep their ruined temples, and the Revantusk have made a village on the eastern coast.",h="The Hinterlands still bear the Amani's old claims, while Wildhammer dwarves hold Aerie Peak.",sec={{t="A Land of Clashing Claims",b="The Amani forest trolls ruled the Hinterlands long before humans or dwarves came to northern Lordaeron. Their defeat in the ancient Troll Wars broke the empire into separate tribes. Centuries later, the War of the Three Hammers drove the Wildhammer dwarves from Grim Batol.\n\nThey migrated north and settled above ground at Aerie Peak. There, they tamed native gryphons and kept their shamanic traditions as they built a great stronghold in the heights. The forest trolls saw them as squatters on ancestral land. Skirmishes and raids have kept the feud alive ever since.",sp=0},{t="Tribes of the Forest",b="Three forest troll tribes occupy the dense woods and ruined temples. The strongest are the brutal Vilebranch, who hold the terraced temple city of Jintha'Alor and the towering Altar of Zul. Farther south, the weaker Witherbark cling to Shadra'Alor and Hiri'Watha.\n\nThe nomadic Revantusk were long scorned by their cousins and had no true home. After the Third War, they made a treaty with Thrall's New Horde. With aid from orcs and Forsaken, they founded Revantusk Village on the eastern sea cliffs and claimed a coastal stronghold of their own.",sp=0},{t="The Slumbering Rift",b="Seradane, the great tree in the northern Hinterlands, shelters a portal to the Emerald Dream. Green dragons and creatures of nature guard the grove. Now the Emerald Nightmare seeps across the portal's threshold, twisting once-benevolent drakes and dragonspawn into furious guardians.",sp=1}},faq={{q="How do I get to the Hinterlands?",a="Travelers from either faction enter the Hinterlands from Hillsbrad Foothills. They go northeast through a mountain pass beyond Durnholde Keep. Alliance travelers follow the road to Aerie Peak, while Horde travelers cross east through the wilderness to Revantusk Village on the coast.",al={"hinterlands entrance","how to enter hinterlands","getting to hinterlands"}},{q="Who rules Aerie Peak?",a="Falstad Wildhammer, Lord of Aerie Peak, leads the Wildhammer clan there. Thane Kurdran Wildhammer led the clan during the Second War.",al={"wildhammer leader","who leads wildhammer","aerie peak ruler"}},{q="Why are the Revantusk trolls allied with the Horde?",a="The nomadic Revantusk sought protection and an end to wandering. The hostile Vilebranch and Witherbark rejected Horde emissaries. The New Horde gave the Revantusk resources and soldiers to build Revantusk Village on the coast, earning their loyalty against local rivals.",al={"revantusk horde","why troll horde hinterlands","revantusk village lore"}},{q="What is Jintha'Alor?",a="Jintha'Alor is an ancient fortress cut into the southern cliffs in many tiers. It is the chief stronghold of the ruthless Vilebranch, with sacrificial altars and elite warriors. Its witch doctors perform blood rites for their dark loas.",al={"jintha'alor lore","troll city hinterlands","vilebranch city"}},{q="What is the Great Tree at Seradane?",a="Seradane, one of Azeroth's Great Trees, shelters a portal to the Emerald Dream. Green dragons and wildkin watch over the grove.",al={"seradane portal","big tree hinterlands","green dragon hinterlands"}},{q="What is Quel'Danil Lodge?",a="Quel'Danil Lodge is a forest retreat kept by Highvale high elves. The Scourge spared it from a direct assault on Quel'Thalas. Its rangers and scholars work with nearby Wildhammer dwarves, sharing intelligence about hostile forest trolls.",al={"high elf lodge hinterlands","queldanil","elves in hinterlands"}}},ang={["race:Dwarf"]="As a Wildhammer or visiting Bronzebeard, you find dwarven life at Aerie Peak beneath open skies. Shamanic power and legendary gryphons shape life there.",["race:Troll"]="In the Hinterlands, ancient Amani glory lives on as bloodlines clash over temple steps. The Revantusk show that forest trolls still have a place in the New Horde.",["faction:Alliance"]="The Wildhammer dwarves prize their fierce independence. Aid their outposts and the high elves of Quel'Danil to build goodwill against shared troll threats.",["faction:Horde"]="Revantusk Village gives the Horde an eastern beachhead in northern Lordaeron. To hold it, you must beat back the fierce Vilebranch.",["class:Druid"]="Seradane's ancient tree is closely tied to the Emerald Dream. Watch carefully for the creeping rot of the Nightmare."},kw={"aerie peak","gryphon","hinterlands","jintha'alor","quel'danil","revantusk","seradane","vilebranch","wildhammer","witherbark"},rel={"topic:wildhammer-clan","topic:new-horde","topic:emerald-dream","topic:troll","subzone:durnholde-keep","zone:arathi","zone:hillsbrad","zone:westernplaguelands"},src={"Hinterlands"}}
